CREATE OR REPLACE FUNCTION public.set_initial_card_pin(p_card_code text, p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  updated_count integer;
BEGIN
  IF length(p_pin) < 6 OR length(p_pin) > 72 THEN
    RETURN false;
  END IF;

  UPDATE public.card
  SET pin_hash = extensions.crypt(
    p_pin,
    extensions.gen_salt('bf')
  )
  WHERE card_code = p_card_code
    AND pin_hash IS NULL;

  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count = 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_card_review_url(p_card_code text, p_pin text, p_review_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_hash text;
  v_attempts integer;
  v_locked_until timestamptz;
BEGIN
  IF p_review_url IS NULL
    OR length(p_review_url) > 2048
    OR p_review_url !~* '^https://(maps\.app\.goo\.gl|www\.google\.com|google\.com|search\.google\.com)/'
  THEN
    RETURN false;
  END IF;

  INSERT INTO public.card_pin_attempts (card_code)
  VALUES (p_card_code)
  ON CONFLICT (card_code) DO NOTHING;

  SELECT attempts, locked_until
  INTO v_attempts, v_locked_until
  FROM public.card_pin_attempts
  WHERE card_code = p_card_code
  FOR UPDATE;

  IF v_locked_until > now() THEN
    RETURN false;
  END IF;

  SELECT pin_hash INTO v_hash
  FROM public.card
  WHERE card_code = p_card_code;

  IF v_hash IS NULL
    OR v_hash <> extensions.crypt(p_pin, v_hash)
  THEN
    UPDATE public.card_pin_attempts
    SET attempts = CASE
          WHEN locked_until <= now() THEN 1
          ELSE attempts + 1
        END,
        locked_until = CASE
          WHEN attempts >= 4 THEN now() + interval '15 minutes'
          ELSE NULL
        END
    WHERE card_code = p_card_code;

    RETURN false;
  END IF;

  UPDATE public.card
  SET review_url = p_review_url
  WHERE card_code = p_card_code;

  UPDATE public.card_pin_attempts
  SET attempts = 0, locked_until = NULL
  WHERE card_code = p_card_code;

  RETURN true;
END;
$function$
